264: void _addReplyProtoToList(client *c, const char *s, size_t len) {
265:     if (c->flags & CLIENT_CLOSE_AFTER_REPLY) return;
266: 
267:     listNode *ln = listLast(c->reply);
268:     clientReplyBlock *tail = ln? listNodeValue(ln): NULL;
269: 
270:     /* Note that 'tail' may be NULL even if we have a tail node, becuase when
271:      * addDeferredMultiBulkLength() is used, it sets a dummy node to NULL just
272:      * fo fill it later, when the size of the bulk length is set. */
273: 
274:     /* Append to tail string when possible. */
275:     if (tail) {
276:         /* Copy the part we can fit into the tail, and leave the rest for a
277:          * new node */
278:         size_t avail = tail->size - tail->used;
279:         size_t copy = avail >= len? len: avail;
280:         memcpy(tail->buf + tail->used, s, copy);
281:         tail->used += copy;
282:         s += copy;
283:         len -= copy;
284:     }
285:     if (len) {
286:         /* Create a new node, make sure it is allocated to at
287:          * least PROTO_REPLY_CHUNK_BYTES */
288:         size_t size = len < PROTO_REPLY_CHUNK_BYTES? PROTO_REPLY_CHUNK_BYTES: len;
289:         tail = zmalloc(size + sizeof(clientReplyBlock));
290:         /* take over the allocation's internal fragmentation */
291:         tail->size = zmalloc_usable(tail) - sizeof(clientReplyBlock);
292:         tail->used = len;
293:         memcpy(tail->buf, s, len);
294:         listAddNodeTail(c->reply, tail);
295:         c->reply_bytes += tail->size;
296:     }
297:     asyncCloseClientOnOutputBufferLimitReached(c);
298: }
