1283:             if (objlen == 0) {
1284:                 c->reply_bytes -= o->size;
1285:                 listDelNode(c->reply,listFirst(c->reply));
1286:                 continue;
1287:             }
1288: 
1289:             nwritten = connWrite(c->conn, o->buf + c->sentlen, objlen - c->sentlen);
